"""Edit Distance — Levenshtein DP.

Each cell is the cheapest of delete, insert, or replace (free when the
characters already match).

Time: O(n*m)   Space: O(m)
"""


class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        previous = list(range(len(word2) + 1))
        for i, a in enumerate(word1, 1):
            current = [i]
            for j, b in enumerate(word2, 1):
                if a == b:
                    current.append(previous[j - 1])
                else:
                    current.append(1 + min(previous[j],        # delete
                                           current[j - 1],     # insert
                                           previous[j - 1]))   # replace
            previous = current
        return previous[-1]
